SELECT 
FROM t_ai_proactive_event
WHERE event_no = #{eventNo}
  AND user_id = #{userId}

SELECT 
FROM t_ai_proactive_event
WHERE user_id = #{userId}
ORDER BY generated_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM t_ai_proactive_event
WHERE subscription_id = #{subscriptionId}
  AND generated_time >= #{since}
  AND status IN ('READY', 'NO_DATA')

SELECT 
FROM t_ai_proactive_event
WHERE subscription_id = #{subscriptionId}
  AND object_type = #{objectType}
  AND object_id = #{objectId}
  AND generated_time >= #{since}
  AND status IN ('READY', 'NO_DATA')
ORDER BY generated_time DESC, id DESC
LIMIT 1
